{
  "case_id": "xsu_sg_004_multiple_impairments",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret rammer udgangspunktet og den samlede vurdering, men udelader helt, at en anden varig funktionsnedsættelse kan inddrages under sagens behandling, hvis ansøgeren ønsker det og indsender fyldestgørende dokumentation. Det betyder, at svaret fremstår som en uddybet lukket regel. Desuden skriver svaret, at vurderingen gælder 'betydningen for erhvervsevnen' og 'aktuelle symptomer', hvilket ikke fremgår af de udleverede passager om flere funktionsnedsættelser. Svaret er derfor ikke juridisk korrekt som helhed."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Tre af de fire kritiske elementer er dækket (samlet vurdering, angivelse og dokumentation, udgangspunkt om de angivne). Det fjerde mangler: inddragelse af en anden varig funktionsnedsættelse under behandlingen ved ønske og fyldestgørende dokumentation, som opfylder minimumskravene. Svaret nævner heller ikke, at journalomtale ikke er nok."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvilke funktionsnedsættelser Udbetaling Danmark vurderer: de ansøgte, og flere vurderes samlet."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til Vejledning nr. 10157 og bruger noteanvisninger. Det er en identificerbar kilde, selvom noterne ikke er præcist knyttet til afsnit."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Den angivne kilde, vejledning VEJ nr. 10157 af 05/10/2026, findes i det frosne materiale og er en autoritativ og anvendelig kilde til spørgsmålet."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Kernepåstandene om udgangspunktet, samlet vurdering og dokumentation støttes af afsnit 3.4.1.2 og 3.5. Påstanden om, at vurderingen sker 'på baggrund af de lægefaglige oplysninger og de aktuelle symptomer' og 'den samlede betydning ... for erhvervsevnen', er ikke støttet af de citerede passager. Kildelisten indeholder også en løs sætning om 'velbeskrevet og lægefagligt dokumenteret', som ikke findes i de udleverede passager."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en vurdering af 'aktuelle symptomer' og et krav om, at funktionsnedsættelsen skal være 'velbeskrevet', som ikke er støttet af de udleverede passager om de relevante afsnit. Det er også tvivlsomt, om 'samlet betydning for erhvervsevnen' er støttet."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "'Som udgangspunkt' er bevaret. Svaret mangler dog undtagelsen om senere inddragelse af en anden varig funktionsnedsættelse og betingelserne ønske, fyldestgørende dokumentation og minimumskrav. Det mangler også, at journalomtale alene ikke er nok."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "De viste trin hænger sammen: udgangspunkt for ansøgte funktionsnedsættelser, samlet vurdering af flere og praktisk anbefaling om angivelse og dokumentation. Konklusionen følger af dem, selvom den er ufuldstændig."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Som udgangspunkt' bruges korrekt, og 'bør' om ansøgerens angivelse og dokumentation er en rimelig, ikke overdrevet formulering. Svaret gør ikke skøn eller undtagelser absolutte."
    }
  },
  "xhaile_coverage": {
    "A16": {
      "label": "yes",
      "reason": "Svaret siger, at flere funktionsnedsættelser vurderes samlet, og at ansøgeren skal dokumentere alle. Det nævner ikke eksplicit, at der skal oplyses, at man søger på flere, men det angives, at ansøgeren skal angive, hvilke der søges på."
    },
    "A24": {
      "label": "partial",
      "reason": "Svaret dækker udgangspunktet og kravet om at angive funktionsnedsættelserne i ansøgningen. Det nævner ikke eksemplet om, at andre funktionsnedsættelser kun omtalt i den lægefaglige dokumentation ikke vurderes."
    },
    "A25": {
      "label": "no",
      "reason": "Svaret nævner ikke muligheden for at inddrage en anden varig funktionsnedsættelse under sagens behandling, ansøgerens initiativ eller minimumskravene til dokumentation."
    }
  },
  "overall_notes": "Svaret er korrekt på udgangspunktet og den samlede vurdering, men det mangler undtagelsen om senere inddragelse af en anden varig funktionsnedsættelse, og det tilføjer elementer (aktuelle symptomer, erhvervsevne, velbeskrevet), som ikke er støttet af de udleverede passager. Kildehenvisningen er til gyldig vejledning, men noterne er upræcise."
}

